// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

import "./constants/addresses.sol";
import "./constants/roles.sol";
import "./interfaces/IRWACalculator.sol";
import "./tangibleInterfaces/ITangibleMarketplace.sol";
import "./tangibleInterfaces/IPriceOracle.sol";
import "./AddressAccessor.sol";

interface ITreasuryTrackerExt is ITreasuryTracker {
    //fractions
    function getFractionContractsInTreasury()
        external
        view
        returns (address[] memory);

    function fractionContractsInTreasurySize() external view returns (uint256);

    function getFractionTokensInTreasury(address ftnft)
        external
        view
        returns (uint256[] memory);

    function fractionTokensInTreasurySize(address ftnft)
        external
        view
        returns (uint256);

    // ftnft on sale
    function getFractionContractsOnSale()
        external
        view
        returns (address[] memory);

    function fractionContractsOnSaleSize() external view returns (uint256);

    function getFractionTokensOnSale(address ftnft)
        external
        view
        returns (uint256[] memory);

    function fractionTokensOnSaleSize(address ftnft)
        external
        view
        returns (uint256);

    //tnfts
    function getTnftCategoriesInTreasury()
        external
        view
        returns (address[] memory);

    function tnftCategoriesInTreasurySize() external view returns (uint256);

    function getTnftTokensInTreasury(address tnft)
        external
        view
        returns (uint256[] memory);

    function tnftTokensInTreasurySize(address tnft)
        external
        view
        returns (uint256);

    //tnfts on sale
    function getTnftCategoriesOnSale() external view returns (address[] memory);

    function tnftCategoriesOnSaleSize() external view returns (uint256);

    function getTnftTokensOnSale(address tnft)
        external
        view
        returns (uint256[] memory);

    function tnftTokensOnSaleSize(address tnft) external view returns (uint256);
}

interface ITNFTPriceManager {
    function itemPriceBatchTokenIds(
        ITangibleNFT nft,
        IERC20 paymentUSDToken,
        uint256[] calldata tokenIds
    )
        external
        view
        returns (
            uint256[] memory weSellAt,
            uint256[] memory weSellAtStock,
            uint256[] memory weBuyAt,
            uint256[] memory weBuyAtStock,
            uint256[] memory lockedAmount
        );

    function itemPriceBatchFingerprints(
        ITangibleNFT nft,
        IERC20 paymentUSDToken,
        uint256[] calldata fingerprints
    )
        external
        view
        returns (
            uint256[] memory weSellAt,
            uint256[] memory weSellAtStock,
            uint256[] memory weBuyAt,
            uint256[] memory weBuyAtStock,
            uint256[] memory lockedAmount
        );

    function getPriceOracleForCategory(ITangibleNFT category)
        external
        view
        returns (IPriceOracle);
}

contract RWACalculator is AddressAccessor, IRWACalculator {
    struct HelperStruct {
        uint256[] weSellAt;
        uint256[] lockedAmount;
        uint256[] tokenIds;
        uint256[] fingerprints;
    }
    struct ContractHolder {
        address reSellManager;
        address goldSellManager;
        address marketplace;
    }
    mapping(address => uint256) public priceThreshold;
    uint256 private immutable fullPercent = 100000;
    address[4] public goldTnfts;

    struct PricesOracleArrays {
        uint256[] weSellAt;
        uint256[] weSellAtStock;
        uint256[] weBuyAt;
        uint256[] weBuyAtStock;
        uint256[] lockedAmount;
    }

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function setGoldTnfts(address[4] memory _goldTnfts)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        goldTnfts = _goldTnfts;
    }

    function setPriceAboveMarketThreshold(address tnft, uint256 threshold)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(threshold >= 100000, "incorrect threshold");
        priceThreshold[tnft] = threshold;
    }

    function _isGoldTnft(address tnft) internal view returns (bool) {
        for (uint256 i; i < 4; i++) {
            if (tnft == goldTnfts[i]) {
                return true;
            }
        }
        return false;
    }

    function _getPriceManager()
        internal
        view
        returns (ITNFTPriceManager priceManager)
    {
        priceManager = ITNFTPriceManager(
            addressProvider.getAddress(TANGIBLE_PRICE_MANAGER_ADDRESS)
        );
    }

    function _getTangibleMarketplace()
        internal
        view
        returns (ITangibleMarketplace marketplace)
    {
        marketplace = ITangibleMarketplace(
            addressProvider.getAddress(TANGIBLE_MARKETPLACE_ADDRESS)
        );
    }

    function _convertToCorrectDecimals(
        uint256 price,
        uint8 salePriceDecimals,
        uint8 treasuryTokenDecimals
    ) internal pure returns (uint256) {
        if (uint256(salePriceDecimals) > treasuryTokenDecimals) {
            return price / (10**(salePriceDecimals - treasuryTokenDecimals));
        } else if (uint256(salePriceDecimals) < treasuryTokenDecimals) {
            return price * (10**(treasuryTokenDecimals - salePriceDecimals));
        }
        return price;
    }

    function calculate(IERC20 treasuryToken)
        external
        view
        returns (
            uint256 usdValueInTreasury,
            uint256 usdValueInVaults,
            uint256 usdValueInEscrow,
            bool valueNotLatest
        )
    {
        (address tracker, address vaultTracker) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TREASURY_TRACKER_ADDRESS, VAULTS_TRACKER_ADDRESS)
            ),
            (address, address)
        );

        (
            usdValueInTreasury,
            usdValueInEscrow,
            valueNotLatest
        ) = ITreasuryTracker(tracker).getRwaUsdValue(
            IERC20Metadata(address(treasuryToken))
        );

        if (vaultTracker != address(0)) {
            //this is actually vaultTracker
            (usdValueInVaults, , valueNotLatest) = ITreasuryTracker(
                vaultTracker
            ).getRwaUsdValue(IERC20Metadata(address(treasuryToken)));
        }
        // add those that are on sale
        usdValueInTreasury += _calculateTnftsOnSale(
            IERC20Metadata(address(treasuryToken))
        );
        usdValueInTreasury += _calculateFtnftsOnSale(
            IERC20Metadata(address(treasuryToken))
        );
        // take value from oracle and mul the usd value
        AggregatorV3Interface daiUsdFeed = AggregatorV3Interface(
            addressProvider.getAddress(DAI_USD_ORACLE_ADDRESS)
        );
        (, int256 price, , , ) = daiUsdFeed.latestRoundData();
        usdValueInTreasury =
            (usdValueInTreasury * uint256(price)) /
            10**uint256(daiUsdFeed.decimals());

        usdValueInEscrow =
            (usdValueInEscrow * uint256(price)) /
            10**uint256(daiUsdFeed.decimals());
    }

    function _calculateTnftsOnSale(IERC20Metadata treasuryToken)
        internal
        view
        returns (uint256 usdValue)
    {
        ContractHolder memory ch;
        (ch.reSellManager, ch.goldSellManager, ch.marketplace) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(
                    RE_SELL_MANAGER_ADDRESS,
                    GOLD_SELL_MANAGER_ADDRESS,
                    TANGIBLE_MARKETPLACE_ADDRESS
                )
            ),
            (address, address, address)
        );
        address[] memory grouped = new address[](2);
        grouped[0] = ch.reSellManager;
        grouped[1] = ch.goldSellManager;
        for (uint256 it; it < 2; it++) {
            address[] memory tnftContracts = ITreasuryTrackerExt(grouped[it])
                .getTnftCategoriesOnSale();
            uint256 categoriesTotal = tnftContracts.length;
            for (uint256 i; i < categoriesTotal; i++) {
                uint256[] memory tnftIds = ITreasuryTrackerExt(grouped[it])
                    .getTnftTokensOnSale(tnftContracts[i]);

                uint256 tnftsTotal = tnftIds.length;
                for (uint256 j; j < tnftsTotal; j++) {
                    ITangibleMarketplace.Lot memory lot = ITangibleMarketplace(
                        ch.marketplace
                    ).marketplace(tnftContracts[i], tnftIds[j]);
                    if (lot.seller == grouped[it]) {
                        usdValue += lot.price;
                        usdValue = _convertToCorrectDecimals(
                            usdValue,
                            IERC20Metadata(address(lot.paymentToken))
                                .decimals(),
                            treasuryToken.decimals()
                        );
                    }
                }
            }
        }
    }

    function _calculateFtnftsOnSale(IERC20Metadata treasuryToken)
        internal
        view
        returns (uint256 usdValue)
    {
        ContractHolder memory ch;
        (ch.reSellManager, ch.goldSellManager, ch.marketplace) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(
                    RE_SELL_MANAGER_ADDRESS,
                    GOLD_SELL_MANAGER_ADDRESS,
                    TANGIBLE_MARKETPLACE_ADDRESS
                )
            ),
            (address, address, address)
        );
        address[] memory grouped = new address[](2);
        grouped[0] = ch.reSellManager;
        grouped[1] = ch.goldSellManager;
        for (uint256 it; it < 2; it++) {
            address[] memory ftnftContracts = ITreasuryTrackerExt(grouped[it])
                .getFractionContractsOnSale();
            uint256 categoriesTotal = ftnftContracts.length;
            for (uint256 i; i < categoriesTotal; i++) {
                uint256[] memory ftnftIds = ITreasuryTrackerExt(grouped[it])
                    .getFractionTokensOnSale(ftnftContracts[i]);

                uint256 tnftsTotal = ftnftIds.length;
                for (uint256 j; j < tnftsTotal; j++) {
                    ITangibleMarketplace.LotFract
                        memory lotFract = ITangibleMarketplace(ch.marketplace)
                            .marketplaceFract(ftnftContracts[i], ftnftIds[j]);
                    //if we haven't updated trackers
                    if (lotFract.seller == grouped[it]) {
                        usdValue += ((lotFract.price *
                            lotFract.nft.fractionShares(ftnftIds[j])) /
                            lotFract.initialShare);
                        usdValue = _convertToCorrectDecimals(
                            usdValue,
                            IERC20Metadata(address(lotFract.paymentToken))
                                .decimals(),
                            treasuryToken.decimals()
                        );
                    }
                }
            }
        }
    }

    function fetchPaymentTokenAndAmountFtnft(
        address ftnft,
        uint256 fractionId,
        uint256 share
    )
        external
        view
        returns (
            IERC20 paymentToken,
            uint256 amount,
            bool inRange
        )
    {
        ITangibleMarketplace tMarketplace = _getTangibleMarketplace();
        IFactoryExt factory = tMarketplace.factory();
        ITangibleMarketplace.LotFract memory lot = tMarketplace
            .marketplaceFract(ftnft, fractionId);
        paymentToken = lot.paymentToken;
        amount = (share * lot.price) / lot.initialShare;
        // check if in range
        HelperStruct memory hs;
        ITangibleNFT tnft = ITangibleFractionsNFT(ftnft).tnft();
        hs.weSellAt = new uint256[](1);
        hs.lockedAmount = new uint256[](1);
        hs.tokenIds = new uint256[](1);
        hs.tokenIds[0] = ITangibleFractionsNFT(ftnft).tnftTokenId();
        ITNFTPriceManager priceManager = _getPriceManager();
        (hs.weSellAt, , , , hs.lockedAmount) = priceManager
            .itemPriceBatchTokenIds(tnft, paymentToken, hs.tokenIds);
        //is the item in our purchase range?

        uint256 topPrice;
        if (lot.seller != factory.initReSeller()) {
            require(
                priceThreshold[address(tnft)] >= 100000,
                "price threshold missing"
            );
            topPrice =
                ((((hs.weSellAt[0] + hs.lockedAmount[0]) * share) / 10000000) *
                    priceThreshold[address(tnft)]) /
                fullPercent;
        } else {
            topPrice = amount;
        }
        if (amount <= topPrice) {
            inRange = true;
        } else {
            inRange = false;
        }
    }

    function fetchPaymentTokenAndAmountTnft(
        address tnft,
        uint256 fingerprint,
        uint256 tokenId,
        uint256 _years,
        bool unminted
    )
        external
        view
        returns (
            IERC20 paymentToken,
            uint256 amount,
            bool inRange
        )
    {
        ITangibleMarketplace tMarketplace = _getTangibleMarketplace();
        if (unminted) {
            paymentToken = IFactoryExt(tMarketplace.factory()).defUSD();
            HelperStruct memory hs;
            hs.weSellAt = new uint256[](1);
            hs.lockedAmount = new uint256[](1);
            hs.fingerprints = new uint256[](1);
            hs.fingerprints[0] = fingerprint;
            ITNFTPriceManager priceManager = _getPriceManager();
            (hs.weSellAt, , , , hs.lockedAmount) = priceManager
                .itemPriceBatchFingerprints(
                    ITangibleNFT(tnft),
                    paymentToken,
                    hs.fingerprints
                );
            amount = hs.weSellAt[0] + hs.lockedAmount[0];
            //check for storage
            amount += _checkStorageValue(ITangibleNFT(tnft), amount, _years);
            inRange = true;
        } else {
            ITangibleMarketplace.Lot memory lot = tMarketplace.marketplace(
                tnft,
                tokenId
            );
            paymentToken = lot.paymentToken;
            amount = lot.price;
            //is the item in our purchase range?
            require(
                priceThreshold[address(tnft)] >= 100000,
                "price threshold missing"
            );
            uint256 topPrice = (amount * priceThreshold[tnft]) / fullPercent;
            // check if in range
            HelperStruct memory hs;
            hs.weSellAt = new uint256[](1);
            hs.lockedAmount = new uint256[](1);
            hs.tokenIds = new uint256[](1);
            hs.tokenIds[0] = tokenId;
            ITNFTPriceManager priceManager = _getPriceManager();
            (hs.weSellAt, , , , hs.lockedAmount) = priceManager
                .itemPriceBatchTokenIds(
                    ITangibleNFT(tnft),
                    paymentToken,
                    hs.tokenIds
                );
            if (amount <= topPrice) {
                inRange = true;
            } else {
                inRange = false;
            }
        }
    }

    function calcFractionNativeValue(address ftnft, uint256 share)
        external
        view
        returns (string memory currency, uint256 value)
    {
        ITangibleNFT tnft = ITangibleFractionsNFT(ftnft).tnft();
        uint256 fingerprint = ITangibleFractionsNFT(ftnft).tnftFingerprint();
        (currency, value) = _getTnftNativeValue(tnft, fingerprint);
        value = (value * share) / 10000000;
    }

    function calcTnftNativeValue(address tnft, uint256 fingerprint)
        external
        view
        returns (string memory currency, uint256 value)
    {
        return _getTnftNativeValue(ITangibleNFT(tnft), fingerprint);
    }

    function _getTnftNativeValue(ITangibleNFT tnft, uint256 fingerprint)
        internal
        view
        returns (string memory currency, uint256 value)
    {
        ITNFTPriceManager priceManager = _getPriceManager();
        IPriceOracle oracle = priceManager.getPriceOracleForCategory(tnft);
        (value, currency) = oracle.marketPriceNativeCurrency(fingerprint);
    }

    function _checkStorageValue(
        ITangibleNFT tnft,
        uint256 price,
        uint256 _years
    ) internal view returns (uint256 storageAmount) {
        if (!tnft.storageRequired()) {
            return storageAmount;
        }
        if (tnft.storagePriceFixed()) {
            storageAmount = tnft.storagePricePerYear() * _years;
        } else {
            require(price > 0, "Price not correct");
            storageAmount =
                (price * tnft.storagePercentagePricePerYear() * _years) /
                10000;
        }
    }
}

contracts/managers/RESellManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

import "../constants/addresses.sol";
import "../constants/roles.sol";
import "../interfaces/ITokenSwap.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IPriceOracle.sol";
import "../interfaces/ITreasuryTracker.sol";
import "../interfaces/IRWACalculator.sol";
import "../tangibleInterfaces/ITangibleMarketplace.sol";
import "../tangibleInterfaces/IInstantLiquidity.sol";
import "../tokens/interfaces/ITangibleERC20.sol";
import "./OnSaleTracker.sol";

contract ReSellManager is OnSaleTracker, IERC721Receiver {
    using SafeERC20 for IERC20;

    address private latestReceivedNFT;
    uint256 private latestReceivedToken;
    address public reTnft;

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function setRETnft(address tnft) external onlyRole(DEFAULT_ADMIN_ROLE) {
        reTnft = tnft;
    }

    function sellTnft(
        IERC20 paymentToken,
        uint256[] calldata tokenIds,
        uint256[] calldata prices
    ) external onlyRole(CONTROLLER_ROLE) {
        address treasury = addressProvider.getAddress(TREASURY_ADDRESS);

        address[] memory contracts = new address[](3);
        bytes[] memory data = new bytes[](3);

        contracts[0] = contracts[2] = reTnft;
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.setApprovalForAll.selector,
            abi.encode(address(this), true)
        );
        data[2] = abi.encodePacked(
            IERC721.setApprovalForAll.selector,
            abi.encode(address(this), false)
        );
        data[1] = abi.encodeWithSelector(
            ReSellManager.sellTnftCb.selector,
            paymentToken,
            tokenIds,
            prices
        );

        //update records
        ITreasury(treasury).multicall(contracts, data);
    }

    function sellTnftCb(
        IERC20 paymentToken,
        uint256[] calldata tokenIds,
        uint256[] calldata prices
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");

        uint256 length = tokenIds.length;
        for (uint256 i; i < length; i++) {
            IERC721(reTnft).safeTransferFrom(
                msg.sender,
                address(this),
                tokenIds[i]
            );
            IERC721(reTnft).approve(marketplace, tokenIds[i]);
            ITreasury(treasury).updateTrackerTnftExt(
                reTnft,
                tokenIds[i],
                false
            );
            //update local tracking mechanism so that we can use it in RWACalculator
            tnftSalePlaced(ITangibleNFT(reTnft), tokenIds[i], true);
        }

        ITangibleMarketplace(marketplace).sellBatch(
            ITangibleNFT(reTnft),
            paymentToken,
            tokenIds,
            prices
        );
    }

    function modifyTnftSale(
        address tnft,
        uint256[] memory tokenIds,
        uint256[] memory prices
    ) external onlyRole(CONTROLLER_ROLE) {
        //put on sale
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        ITangibleMarketplace.Lot memory lot = ITangibleMarketplace(marketplace)
            .marketplace(tnft, tokenIds[0]);

        ITangibleMarketplace(marketplace).sellBatch(
            ITangibleNFT(tnft),
            lot.paymentToken,
            tokenIds,
            prices
        );
    }

    function sellFtnft(
        address ftnft,
        IERC20 paymentToken,
        uint256[] calldata shares,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        address treasury = addressProvider.getAddress(TREASURY_ADDRESS);

        require(
            reTnft == _fetchReAddressFromFraction(ftnft),
            "fraction is not re!!"
        );

        address[] memory contracts = new address[](2);
        bytes[] memory data = new bytes[](2);

        contracts[0] = ftnft;
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.approve.selector,
            abi.encode(address(this), tokenId)
        );
        data[1] = abi.encodeWithSelector(
            ReSellManager.sellFtnftCb.selector,
            ftnft,
            paymentToken,
            shares,
            tokenId,
            price,
            minPurchaseShare
        );

        //update records
        ITreasury(treasury).multicall(contracts, data);
    }

    function sellFtnftCb(
        address ftnft,
        IERC20 paymentToken,
        uint256[] calldata shares,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");
        //take it from treasury
        IERC721(ftnft).safeTransferFrom(treasury, address(this), tokenId);
        //update tracker correctly
        if (ITangibleFractionsNFT(ftnft).fractionShares(tokenId) == shares[0]) {
            ITreasury(treasury).updateTrackerFtnftExt(ftnft, tokenId, false);
            //update local tracking mechanism so that we can use it in RWACalculator
            ftnftSalePlaced(ITangibleFractionsNFT(ftnft), tokenId, true);
        } else {
            // we are not selling everything
            ITreasuryTracker(treasury).updateFractionData(
                address(ftnft),
                tokenId
            );
        }
        //approve
        IERC721(ftnft).approve(marketplace, tokenId);
        //put on sale
        ITangibleMarketplace(marketplace).sellFraction(
            ITangibleFractionsNFT(ftnft),
            paymentToken,
            tokenId,
            shares,
            price,
            minPurchaseShare
        );
    }

    function modifyFtnftSale(
        address ftnft,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        //put on sale
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        ITangibleMarketplace.LotFract memory lf = ITangibleMarketplace(
            marketplace
        ).marketplaceFract(ftnft, tokenId);
        uint256[] memory shares = new uint256[](2);

        ITangibleMarketplace(marketplace).sellFraction(
            ITangibleFractionsNFT(ftnft),
            lf.paymentToken,
            tokenId,
            shares,
            price,
            minPurchaseShare
        );
    }

    function sellFtnftInitial(
        IERC20 paymentToken,
        uint256 keepShare,
        uint256 sellShare,
        uint256 tokenId,
        uint256 sellSharePrice,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        address treasury = addressProvider.getAddress(TREASURY_ADDRESS);

        address[] memory contracts = new address[](2);
        bytes[] memory data = new bytes[](2);

        contracts[0] = reTnft;
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.approve.selector,
            abi.encode(address(this), tokenId)
        );
        data[1] = abi.encodeWithSelector(
            ReSellManager.sellFtnftInitialCb.selector,
            paymentToken,
            keepShare,
            sellShare,
            tokenId,
            sellSharePrice,
            minPurchaseShare
        );

        ITreasury(treasury).multicall(contracts, data);
    }

    function sellFtnftInitialCb(
        IERC20 paymentToken,
        uint256 keepShare,
        uint256 sellShare,
        uint256 tokenId,
        uint256 sellSharePrice,
        uint256 minPurchaseShare
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");

        IERC721(reTnft).safeTransferFrom(treasury, address(this), tokenId);
        IERC721(reTnft).approve(marketplace, tokenId);
        ITangibleMarketplace(marketplace).sellFractionInitial(
            ITangibleNFT(reTnft),
            paymentToken,
            tokenId,
            keepShare,
            sellShare,
            sellSharePrice,
            minPurchaseShare
        );
        ITreasury(treasury).updateTrackerTnftExt(reTnft, tokenId, false);
        if (keepShare != 0) {
            ITreasury(treasury).updateTrackerFtnftExt(
                latestReceivedNFT,
                latestReceivedToken,
                true
            );
        }
    }

    function stopSellFtnft(address ftnft, uint256 tokenId)
        external
        onlyRole(CONTROLLER_ROLE)
    {
        require(
            reTnft == _fetchReAddressFromFraction(ftnft),
            "fraction is not re!!"
        );
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        ITangibleMarketplace(marketplace).stopFractSale(
            ITangibleFractionsNFT(ftnft),
            tokenId
        );
        //update records
        IERC721(ftnft).safeTransferFrom(address(this), treasury, tokenId);
        ITreasury(treasury).updateTrackerFtnftExt(ftnft, tokenId, true);
        //update local tracking mechanism so that we can use it in RWACalculator
        ftnftSalePlaced(ITangibleFractionsNFT(ftnft), tokenId, false);
    }

    function stopSellTnft(uint256[] calldata tokenIds)
        external
        onlyRole(CONTROLLER_ROLE)
    {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        uint256 length = tokenIds.length;
        ITangibleMarketplace(marketplace).stopBatchSale(
            ITangibleNFT(reTnft),
            tokenIds
        );
        //update records
        for (uint256 i = 0; i < length; i++) {
            IERC721(reTnft).safeTransferFrom(
                address(this),
                treasury,
                tokenIds[i]
            );
            ITreasury(treasury).updateTrackerTnftExt(reTnft, tokenIds[i], true);
            //update local tracking mechanism so that we can use it in RWACalculator
            tnftSalePlaced(ITangibleNFT(reTnft), tokenIds[i], false);
        }
    }

    function _fetchReAddressFromFraction(address ftnft)
        internal
        view
        returns (address reAddress)
    {
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        IFactoryExt factory = ITangibleMarketplace(marketplace).factory();
        reAddress = address(
            factory.fractionToTnftAndId(ITangibleFractionsNFT(ftnft)).tnft
        );
    }

    function withdrawToken(IERC20 token) external {
        if (
            !hasRole(DEFAULT_ADMIN_ROLE, msg.sender) &&
            !hasRole(CONTROLLER_ROLE, msg.sender)
        ) {
            revert(
                string(
                    abi.encodePacked(
                        "AccessControl: account ",
                        Strings.toHexString(uint160(msg.sender), 20),
                        " is missing role ",
                        Strings.toHexString(uint256(DEFAULT_ADMIN_ROLE), 32),
                        " or ",
                        Strings.toHexString(uint256(CONTROLLER_ROLE), 32)
                    )
                )
            );
        }
        (address underlying, address tngbl) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(UNDERLYING_ADDRESS, TNGBL_ADDRESS)
            ),
            (address, address)
        );
        if ((address(token) == tngbl) || (address(token) == underlying)) {
            require(
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
                "tngbl and uderlying not alowed"
            );
        }
        token.safeTransfer(msg.sender, token.balanceOf(address(this)));
    }

    function onERC721Received(
        address operator,
        address seller,
        uint256 tokenId,
        bytes calldata data
    ) external override returns (bytes4) {
        return _onERC721Received(operator, seller, tokenId, data);
    }

    function _onERC721Received(
        address, /*operator*/
        address, /*seller*/
        uint256 tokenId, /*tokenId*/
        bytes calldata /*data*/
    ) private returns (bytes4) {
        latestReceivedNFT = msg.sender;
        latestReceivedToken = tokenId;
        return IERC721Receiver.onERC721Received.selector;
    }
}

contracts/managers/OnSaleTracker.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "../tangibleInterfaces/ITangibleInterfaces.sol";
import "../AddressAccessor.sol";
import "../constants/roles.sol";

abstract contract OnSaleTracker is AddressAccessor {
    struct TokenArray {
        uint256[] tokenIds;
    }
    struct ContractItem {
        bool selling;
        uint256 index;
    }

    struct TnftSaleItem {
        ITangibleNFT tnft;
        uint256 tokenId;
        uint256 indexInCurrentlySelling;
    }

    struct FractionSaleItem {
        ITangibleFractionsNFT ftnft;
        uint256 fractionId;
        uint256 indexInCurrentlySelling;
    }

    ITangibleFractionsNFT[] public fractionContractsOnSale;
    mapping(ITangibleFractionsNFT => ContractItem) public isFtnftOnSale;
    mapping(ITangibleFractionsNFT => uint256[]) public fractionTokensOnSale;
    mapping(ITangibleFractionsNFT => mapping(uint256 => FractionSaleItem))
        public fractionSaleMapper;

    //return whole array
    function getFractionContractsOnSale()
        external
        view
        returns (ITangibleFractionsNFT[] memory)
    {
        return fractionContractsOnSale;
    }

    //return size
    function fractionContractsOnSaleSize() external view returns (uint256) {
        return fractionContractsOnSale.length;
    }

    //return whole array
    function getFractionTokensOnSale(ITangibleFractionsNFT ftnft)
        external
        view
        returns (uint256[] memory)
    {
        return fractionTokensOnSale[ftnft];
    }

    //return whole batch arrays
    function getFractionTokensOnSaleBatch(
        ITangibleFractionsNFT[] calldata ftnfts
    ) external view returns (TokenArray[] memory result) {
        uint256 length = ftnfts.length;
        result = new TokenArray[](length);
        for (uint256 i; i < length; i++) {
            TokenArray memory temp = TokenArray(
                fractionTokensOnSale[ftnfts[i]]
            );
            result[i] = temp;
        }
        return result;
    }

    //return size
    function fractionTokensOnSaleSize(ITangibleFractionsNFT ftnft)
        external
        view
        returns (uint256)
    {
        return fractionTokensOnSale[ftnft].length;
    }

    ITangibleNFT[] public tnftCategoriesOnSale;
    mapping(ITangibleNFT => ContractItem) public isTnftOnSale;
    mapping(ITangibleNFT => uint256[]) public tnftTokensOnSale;
    mapping(ITangibleNFT => mapping(uint256 => TnftSaleItem))
        public tnftSaleMapper;

    //return whole array
    function getTnftCategoriesOnSale()
        external
        view
        returns (ITangibleNFT[] memory)
    {
        return tnftCategoriesOnSale;
    }

    //return size
    function tnftCategoriesOnSaleSize() external view returns (uint256) {
        return tnftCategoriesOnSale.length;
    }

    //return whole array
    function getTnftTokensOnSale(ITangibleNFT tnft)
        external
        view
        returns (uint256[] memory)
    {
        return tnftTokensOnSale[tnft];
    }

    //return whole batch arrays
    function getTnftTokensOnSaleBatch(ITangibleNFT[] calldata tnfts)
        external
        view
        returns (TokenArray[] memory result)
    {
        uint256 length = tnfts.length;
        result = new TokenArray[](length);
        for (uint256 i; i < length; i++) {
            TokenArray memory temp = TokenArray(tnftTokensOnSale[tnfts[i]]);
            result[i] = temp;
        }
        return result;
    }

    //return size
    function tnftTokensOnSaleSize(ITangibleNFT tnft)
        external
        view
        returns (uint256)
    {
        return tnftTokensOnSale[tnft].length;
    }

    function tnftSalePlacedExt(
        ITangibleNFT tnft,
        uint256 tokenId,
        bool place
    ) external onlyRole(CONTROLLER_ROLE) {
        tnftSalePlaced(tnft, tokenId, place);
    }

    function tnftSalePlaced(
        ITangibleNFT tnft,
        uint256 tokenId,
        bool place
    ) internal {
        if (place) {
            //check if something from this category is on sale already
            if (!isTnftOnSale[tnft].selling) {
                //add category to actively selling list
                tnftCategoriesOnSale.push(tnft);
                isTnftOnSale[tnft].selling = true;
                isTnftOnSale[tnft].index = tnftCategoriesOnSale.length - 1;
            }
            //something is added to marketplace

            tnftTokensOnSale[tnft].push(tokenId);
            TnftSaleItem memory tsi = TnftSaleItem(
                tnft,
                tokenId,
                (tnftTokensOnSale[tnft].length - 1)
            );
            tnftSaleMapper[tnft][tokenId] = tsi;
        } else {
            //something is removed from marketplace
            uint256 indexInTokenSale = tnftSaleMapper[tnft][tokenId]
                .indexInCurrentlySelling;
            _removeCurrentlySellingTnft(tnft, indexInTokenSale);
            delete tnftSaleMapper[tnft][tokenId];
            if (tnftTokensOnSale[tnft].length == 0) {
                //all tokens are removed, nothing in category is selling anymore
                _removeCategory(isTnftOnSale[tnft].index);
                delete isTnftOnSale[tnft];
            }
        }
    }

    function ftnftSalePlacedExt(
        ITangibleFractionsNFT ftnft,
        uint256 tokenId,
        bool place
    ) external onlyRole(CONTROLLER_ROLE) {
        ftnftSalePlaced(ftnft, tokenId, place);
    }

    function ftnftSalePlaced(
        ITangibleFractionsNFT ftnft,
        uint256 tokenId,
        bool place
    ) internal {
        if (place) {
            //check if something from this category is on sale already
            if (!isFtnftOnSale[ftnft].selling) {
                //add category to actively selling list
                fractionContractsOnSale.push(ftnft);
                isFtnftOnSale[ftnft].selling = true;
                isFtnftOnSale[ftnft].index = fractionContractsOnSale.length - 1;
            }
            //something is added to marketplace
            fractionTokensOnSale[ftnft].push(tokenId);
            FractionSaleItem memory fsi = FractionSaleItem(
                ftnft,
                tokenId,
                (fractionTokensOnSale[ftnft].length - 1)
            );
            fractionSaleMapper[ftnft][tokenId] = fsi;
        } else {
            //something is removed from marketplace
            uint256 indexInTokenSale = fractionSaleMapper[ftnft][tokenId]
                .indexInCurrentlySelling;
            _removeCurrentlySellingFraction(ftnft, indexInTokenSale);
            delete fractionSaleMapper[ftnft][tokenId];
            if (fractionTokensOnSale[ftnft].length == 0) {
                //all tokens are removed, nothing in category is selling anymore
                _removeFraction(isFtnftOnSale[ftnft].index);
                delete isFtnftOnSale[ftnft];
            }
        }
    }

    //this function is not preserving order, and we don't care about it
    function _removeCurrentlySellingFraction(
        ITangibleFractionsNFT ftnft,
        uint256 index
    ) internal {
        require(index < fractionTokensOnSale[ftnft].length, "IndexF");
        //take last token
        uint256 tokenId = fractionTokensOnSale[ftnft][
            fractionTokensOnSale[ftnft].length - 1
        ];

        //replace it with the one we are removing
        fractionTokensOnSale[ftnft][index] = tokenId;
        //set it's new index in saleData
        fractionSaleMapper[ftnft][tokenId].indexInCurrentlySelling = index;
        fractionTokensOnSale[ftnft].pop();
    }

    //this function is not preserving order, and we don't care about it
    function _removeCurrentlySellingTnft(ITangibleNFT tnft, uint256 index)
        internal
    {
        require(index < tnftTokensOnSale[tnft].length, "IndexT");
        //take last token
        uint256 tokenId = tnftTokensOnSale[tnft][
            tnftTokensOnSale[tnft].length - 1
        ];

        //replace it with the one we are removing
        tnftTokensOnSale[tnft][index] = tokenId;
        //set it's new index in saleData
        tnftSaleMapper[tnft][tokenId].indexInCurrentlySelling = index;
        tnftTokensOnSale[tnft].pop();
    }

    function _removeCategory(uint256 index) internal {
        require(index < tnftCategoriesOnSale.length, "IndexC");
        //take last token
        ITangibleNFT _tnft = tnftCategoriesOnSale[
            tnftCategoriesOnSale.length - 1
        ];

        //replace it with the one we are removing
        tnftCategoriesOnSale[index] = _tnft;
        //set it's new index in saleData
        isTnftOnSale[_tnft].index = index;
        tnftCategoriesOnSale.pop();
    }

    function _removeFraction(uint256 index) internal {
        require(index < fractionContractsOnSale.length, "IndexFr");
        //take last token
        ITangibleFractionsNFT _ftnft = fractionContractsOnSale[
            fractionContractsOnSale.length - 1
        ];

        //replace it with the one we are removing
        fractionContractsOnSale[index] = _ftnft;
        //set it's new index in saleData
        isFtnftOnSale[_ftnft].index = index;
        fractionContractsOnSale.pop();
    }
}

