// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import "../constants/addresses.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/ITokenSwap.sol";
import "../AddressAccessor.sol";

interface IUSDRExchange {
    struct MintingStats {
        uint256 tngblToUSDR;
        uint256 underlyingToUSDR;
        uint256 usdrToPromissory;
        uint256 usdrToTNGBL;
        uint256 usdrToUnderlying;
        uint256 usdrFromGains;
        uint256 usdrFromRebase;
    }

    function mintingStats() external view returns (MintingStats memory);
}

interface IUSDR is IERC20Upgradeable {
    function totalSupply() external view returns (uint256);
}

abstract contract PurchaseManager is AddressAccessor {
    uint256 public swapThreshold = 10000; // 0.1%

    function changeSwapThreshold(uint256 _swapThreshold)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        swapThreshold = _swapThreshold;
    }

    function _validatePurchase(uint256 amount) internal view {
        if (amount == 0) {
            return; // all good, no underlying spending, only usdr
        }
        (address treasury, address underlying, address usdr) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TREASURY_ADDRESS, UNDERLYING_ADDRESS, USDR_ADDRESS)
            ),
            (address, address, address)
        );

        uint256 stableMintedRedeemedThreshold = uint256(
            ITreasury(treasury).purchaseStableMintedRedeemedThreshold()
        );

        uint256 totalSTValue = IERC20(underlying).balanceOf(treasury);
        // we can spend % of underlying compared to marketcap

        // we can spend only what is above 10% of marketcap
        uint256 percentMarketcapValue = _convertToCorrectDecimals(
            ((IUSDR(usdr).totalSupply() * stableMintedRedeemedThreshold) / 100),
            IERC20Metadata(usdr).decimals(),
            IERC20Metadata(underlying).decimals()
        );
        //amount we want to spend must be
        // amount < (totalSTValue - percentMarketcapValue) | maxSpendMintedRedeemedValue
        uint256 ableToSpend = percentMarketcapValue < totalSTValue
            ? (totalSTValue - percentMarketcapValue)
            : 0;

        require(
            ableToSpend >= amount,
            string(
                abi.encodePacked(
                    "ST ",
                    Strings.toString(ableToSpend),
                    " not enough for amount ",
                    Strings.toString(amount)
                )
            )
        );
    }

    //need to add second part - to convert treasury token to payment token
    function _convertTreasuryTokenToPayment(
        IERC20 paymentToken,
        uint256 amountReserveToken,
        bool instantLiquidity_,
        uint256 itemPrice,
        uint256 toFillUpToItemPrice
    ) internal {
        (
            address instantLiquidity,
            address marketplace,
            address tokenSwap,
            address underlying
        ) = abi.decode(
                addressProvider.getAddresses(
                    abi.encode(
                        INSTANT_LIQUIDITY_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        TOKEN_SWAP_ADDRESS,
                        UNDERLYING_ADDRESS
                    )
                ),
                (address, address, address, address)
            );
        IERC20(underlying).approve(tokenSwap, amountReserveToken);
        ITokenSwap(tokenSwap).exchange(
            underlying,
            address(paymentToken),
            amountReserveToken,
            toFillUpToItemPrice,
            ITokenSwap.EXCHANGE_TYPE.EXACT_OUTPUT
        );

        if (!instantLiquidity_) {
            paymentToken.approve(marketplace, itemPrice);
        } else {
            paymentToken.approve(instantLiquidity, itemPrice);
        }
    }

    function _convertToCorrectDecimals(
        uint256 price,
        uint8 inTokenDecimals,
        uint8 outTokenDecimals
    ) internal pure returns (uint256) {
        if (uint256(inTokenDecimals) > outTokenDecimals) {
            return price / (10**(inTokenDecimals - outTokenDecimals));
        } else if (uint256(inTokenDecimals) < outTokenDecimals) {
            return price * (10**(outTokenDecimals - inTokenDecimals));
        }
        return price;
    }

    function _checkPaymentTokenAndAmountNeeded(
        IERC20 paymentToken,
        uint256 amount
    ) internal view returns (uint256 reserveAmount) {
        if (amount == 0) {
            return reserveAmount;
        }
        (address tokenSwap, address underlying) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TOKEN_SWAP_ADDRESS, UNDERLYING_ADDRESS)
            ),
            (address, address)
        );
        uint8 paymentDecimals = IERC20Metadata(address(paymentToken))
            .decimals();
        uint8 underlyingDecimals = IERC20Metadata(underlying).decimals();
        // we use this algorithm because curve doesn't have ability to calculate quoteIn
        reserveAmount = _convertToCorrectDecimals(
            amount,
            paymentDecimals,
            underlyingDecimals
        );
        uint256 calcAmount;
        do {
            calcAmount = ITokenSwap(tokenSwap).quoteOut(
                underlying,
                address(paymentToken),
                reserveAmount
            );

            if (calcAmount < amount) {
                reserveAmount =
                    reserveAmount +
                    _convertToCorrectDecimals(
                        amount - calcAmount,
                        paymentDecimals,
                        underlyingDecimals
                    ) +
                    10**uint256(underlyingDecimals); // add 1 dollar
            }
        } while (calcAmount < amount);
        uint256 scaledReserveAmount = _convertToCorrectDecimals(
            reserveAmount,
            underlyingDecimals,
            paymentDecimals
        );
        if (scaledReserveAmount > calcAmount) {
            require(
                (scaledReserveAmount - calcAmount) <
                    (calcAmount * swapThreshold) / 10000000,
                "over threshold"
            );
        }
    }
}

contracts/managers/REPurchaseManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

import "../constants/addresses.sol";
import "../constants/roles.sol";
import "../interfaces/ITokenSwap.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IPriceOracle.sol";
import "../interfaces/ITreasuryTracker.sol";
import "../interfaces/IRWACalculator.sol";
import "../tangibleInterfaces/ITangibleMarketplace.sol";
import "../tangibleInterfaces/IInstantLiquidity.sol";
import "../tokens/interfaces/ITangibleERC20.sol";
import "../AddressAccessor.sol";
import "./PurchaseManager.sol";

contract RePurchaseManager is PurchaseManager, IERC721Receiver {
    using SafeERC20 for IERC20;

    address private latestReceivedNFT;
    uint256 private latestReceivedToken;
    address public reTnft;

    struct HelperStruct {
        address rwaCalculator;
        address treasury;
        IERC20 paymentToken;
        uint256 amount;
        uint256 amountOfPaymentToken;
        bool inRange;
    }

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function setRETnft(address tnft) external onlyRole(DEFAULT_ADMIN_ROLE) {
        reTnft = tnft;
    }

    function purchaseTnft(
        uint256 fingerprint,
        uint256 tokenId,
        uint256 _years,
        bool onlyLock
    ) external onlyRole(CONTROLLER_ROLE) {
        //check payment token and swap if necessary
        HelperStruct memory hs;
        address[] memory contracts = new address[](3);
        contracts[2] = address(this);
        (hs.rwaCalculator, hs.treasury, contracts[0]) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(
                    RWA_CALCULATOR_ADDRESS,
                    TREASURY_ADDRESS,
                    UNDERLYING_ADDRESS
                )
            ),
            (address, address, address)
        );

        (hs.paymentToken, hs.amount, hs.inRange) = IRWACalculator(
            hs.rwaCalculator
        ).fetchPaymentTokenAndAmountTnft(
                reTnft,
                fingerprint,
                tokenId,
                _years,
                tokenId == 0 ? true : false
            );
        // take payment token
        contracts[1] = address(hs.paymentToken);
        require(hs.inRange, "price above range");
        // if treasury has paymentToken, use it
        if (hs.amount <= hs.paymentToken.balanceOf(hs.treasury)) {
            hs.amountOfPaymentToken = hs.amount;
            hs.amount = 0;
        } else {
            hs.amountOfPaymentToken = hs.paymentToken.balanceOf(hs.treasury);
            hs.amount -= hs.amountOfPaymentToken;
        }
        uint256 reserveAmount = _checkPaymentTokenAndAmountNeeded(
            hs.paymentToken,
            hs.amount
        );

        _validatePurchase(reserveAmount);

        bytes[] memory data = new bytes[](3);

        data[0] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), reserveAmount)
        );
        data[1] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), hs.amountOfPaymentToken)
        );
        data[2] = abi.encodePacked(
            RePurchaseManager.purchaseTnftCb.selector,
            abi.encode(
                hs.paymentToken,
                fingerprint,
                tokenId,
                _years,
                hs.amount,
                reserveAmount,
                hs.amountOfPaymentToken,
                onlyLock
            )
        );

        ITreasury(hs.treasury).multicall(contracts, data);
    }

    function purchaseTnftCb(
        IERC20 paymentToken,
        uint256 fingerprint,
        uint256 tokenId,
        uint256 _years,
        uint256 amountToFillUp,
        uint256 reserveAmount,
        uint256 amountOfPaymentToken,
        bool onlyLock
    ) external {
        (address underlying, address marketplace, address treasury) = abi
            .decode(
                addressProvider.getAddresses(
                    abi.encode(
                        UNDERLYING_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        TREASURY_ADDRESS
                    )
                ),
                (address, address, address)
            );
        require(msg.sender == treasury, "not invoked by treasury");
        //take paymentToken
        paymentToken.safeTransferFrom(
            treasury,
            address(this),
            amountOfPaymentToken
        );
        //take the underlying from treasury
        if (reserveAmount > 0) {
            IERC20(underlying).safeTransferFrom(
                treasury,
                address(this),
                reserveAmount
            );
            //convert to paymentToken only reserveAmount
            _convertTreasuryTokenToPayment(
                paymentToken,
                reserveAmount,
                false,
                amountToFillUp + amountOfPaymentToken,
                amountToFillUp
            );
        } else {
            paymentToken.approve(marketplace, amountOfPaymentToken);
        }

        if (tokenId == 0) {
            ITangibleMarketplace(marketplace).buyUnminted(
                ITangibleNFT(reTnft),
                fingerprint,
                _years,
                onlyLock
            );
        } else {
            ITangibleMarketplace(marketplace).buy(
                ITangibleNFT(reTnft),
                tokenId,
                _years
            );
        }
        //send to treasury
        IERC721(reTnft).safeTransferFrom(
            address(this),
            treasury,
            latestReceivedToken
        );
        //send the remaining payment token
        if (paymentToken.balanceOf(address(this)) > 0) {
            paymentToken.safeTransfer(
                treasury,
                paymentToken.balanceOf(address(this))
            );
        }
        // update records
        ITreasury(treasury).updateTrackerTnftExt(
            reTnft,
            latestReceivedToken,
            true
        );
    }

    function purchaseFtnft(
        address ftnft,
        uint256 fractTokenId,
        uint256 share
    ) external onlyRole(CONTROLLER_ROLE) {
        HelperStruct memory hs;
        (
            address rwaCalculator,
            address treasury,
            address marketplace,
            address underlying
        ) = abi.decode(
                addressProvider.getAddresses(
                    abi.encode(
                        RWA_CALCULATOR_ADDRESS,
                        TREASURY_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        UNDERLYING_ADDRESS
                    )
                ),
                (address, address, address, address)
            );
        (hs.paymentToken, hs.amount, hs.inRange) = IRWACalculator(rwaCalculator)
            .fetchPaymentTokenAndAmountFtnft(ftnft, fractTokenId, share);
        //we neglect inRange if it is initial sale of house
        if (
            ITangibleMarketplace(marketplace)
                .factory()
                .fractionToTnftAndId(ITangibleFractionsNFT(ftnft))
                .initialSaleDone
        ) {
            require(hs.inRange, "price above range");
        }
        // if treasury has paymentToken, use it
        if (hs.amount <= hs.paymentToken.balanceOf(treasury)) {
            hs.amountOfPaymentToken = hs.amount;
            hs.amount = 0;
        } else {
            hs.amountOfPaymentToken = hs.paymentToken.balanceOf(treasury);
            hs.amount -= hs.amountOfPaymentToken;
        }
        uint256 reserveAmount = _checkPaymentTokenAndAmountNeeded(
            hs.paymentToken,
            hs.amount
        );

        _validatePurchase(reserveAmount);

        require(
            reTnft == _fetchReAddressFromFraction(ftnft),
            "fraction is not re!!"
        );

        address[] memory contracts = new address[](3);
        bytes[] memory data = new bytes[](3);

        contracts[0] = underlying;
        contracts[1] = address(hs.paymentToken);
        contracts[2] = address(this);

        data[0] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), reserveAmount)
        );
        data[1] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), hs.amountOfPaymentToken)
        );
        data[2] = abi.encodePacked(
            RePurchaseManager.purchaseFtnftCb.selector,
            abi.encode(
                ftnft,
                hs.paymentToken,
                fractTokenId,
                share,
                reserveAmount,
                hs.amount,
                hs.amountOfPaymentToken
            )
        );

        ITreasury(treasury).multicall(contracts, data);
    }

    function purchaseFtnftCb(
        address ftnft,
        IERC20 paymentToken,
        uint256 fractTokenId,
        uint256 share,
        uint256 reserveAmount,
        uint256 amountToFillUp,
        uint256 amountOfPaymentToken
    ) external {
        (address underlying, address marketplace, address treasury) = abi
            .decode(
                addressProvider.getAddresses(
                    abi.encode(
                        UNDERLYING_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        TREASURY_ADDRESS
                    )
                ),
                (address, address, address)
            );

        require(msg.sender == treasury, "not invoked by treasury");
        // take paymentTokenfrom treasury
        paymentToken.safeTransferFrom(
            treasury,
            address(this),
            amountOfPaymentToken
        );
        //take the underlying from treasury
        if (reserveAmount > 0) {
            IERC20(underlying).safeTransferFrom(
                treasury,
                address(this),
                reserveAmount
            );
            //convert to paymentToken
            _convertTreasuryTokenToPayment(
                paymentToken,
                reserveAmount,
                false,
                amountToFillUp + amountOfPaymentToken,
                amountToFillUp
            );
        } else {
            paymentToken.approve(marketplace, amountOfPaymentToken);
        }
        IFactoryExt factory = ITangibleMarketplace(marketplace).factory();
        //check if this ftnft is in initailSale - that means when bought
        //you can't move the token unless sale is complete
        //that is why actuall purchase must be done from
        //treasury in else branch
        if (
            factory
                .fractionToTnftAndId(ITangibleFractionsNFT(ftnft))
                .initialSaleDone
        ) {
            ITangibleMarketplace(marketplace).buyFraction(
                ITangibleFractionsNFT(ftnft),
                fractTokenId,
                share
            );

            //send to treasury
            IERC721(ftnft).safeTransferFrom(
                address(this),
                treasury,
                latestReceivedToken
            );
            //send the remaining payment token
            if (paymentToken.balanceOf(address(this)) > 0) {
                paymentToken.safeTransfer(
                    treasury,
                    paymentToken.balanceOf(address(this))
                );
            }
            //update records
            ITreasury(treasury).updateTrackerFtnftExt(
                ftnft,
                latestReceivedToken,
                true
            );
        } else {
            //send converted token back to treasury and buy it from there
            paymentToken.safeTransfer(
                treasury,
                amountToFillUp + amountOfPaymentToken
            );

            ITreasury(treasury).purchaseReInitialSale(
                paymentToken,
                ftnft,
                fractTokenId,
                share,
                amountToFillUp + amountOfPaymentToken
            );
        }
        //
    }

    function _fetchReAddressFromFraction(address ftnft)
        internal
        view
        returns (address reAddress)
    {
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        IFactoryExt factory = ITangibleMarketplace(marketplace).factory();
        reAddress = address(
            factory.fractionToTnftAndId(ITangibleFractionsNFT(ftnft)).tnft
        );
    }

    function onERC721Received(
        address operator,
        address seller,
        uint256 tokenId,
        bytes calldata data
    ) external override returns (bytes4) {
        return _onERC721Received(operator, seller, tokenId, data);
    }

    function _onERC721Received(
        address, /*operator*/
        address, /*seller*/
        uint256 tokenId, /*tokenId*/
        bytes calldata /*data*/
    ) private returns (bytes4) {
        latestReceivedNFT = msg.sender;
        latestReceivedToken = tokenId;
        return IERC721Receiver.onERC721Received.selector;
    }
}

contracts/managers/GoldSellManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

import "../constants/addresses.sol";
import "../constants/roles.sol";
import "../interfaces/ITokenSwap.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IPriceOracle.sol";
import "../interfaces/ITreasuryTracker.sol";
import "../interfaces/IRWACalculator.sol";
import "../tangibleInterfaces/ITangibleMarketplace.sol";
import "../tangibleInterfaces/IInstantLiquidity.sol";
import "../tokens/interfaces/ITangibleERC20.sol";
import "./OnSaleTracker.sol";

contract GoldSellManager is OnSaleTracker, IERC721Receiver {
    using SafeERC20 for IERC20;

    enum GOLD_WEIGHT {
        XAU100,
        XAU250,
        XAU500,
        XAU1000,
        OUT
    }

    address private latestReceivedNFT;
    uint256 private latestReceivedToken;
    address[4] public goldTnfts;

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function setGoldTnfts(address[4] memory _goldTnfts)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        goldTnfts = _goldTnfts;
    }

    function sellTnft(
        GOLD_WEIGHT goldIndex,
        IERC20 paymentToken,
        uint256[] calldata tokenIds,
        uint256[] calldata prices
    ) external onlyRole(CONTROLLER_ROLE) {
        require(goldIndex < GOLD_WEIGHT.OUT, "no such gold");

        address[] memory contracts = new address[](3);
        bytes[] memory data = new bytes[](3);

        contracts[0] = contracts[2] = goldTnfts[uint256(goldIndex)];
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.setApprovalForAll.selector,
            abi.encode(address(this), true)
        );
        data[1] = abi.encodePacked(
            GoldSellManager.sellTnftCb.selector,
            abi.encode(goldIndex, paymentToken, tokenIds, prices)
        );
        data[2] = abi.encodePacked(
            IERC721.setApprovalForAll.selector,
            abi.encode(address(this), false)
        );

        //update records
        address treasury = addressProvider.getAddress(TREASURY_ADDRESS);
        ITreasury(treasury).multicall(contracts, data);
    }

    function sellTnftCb(
        GOLD_WEIGHT goldIndex,
        IERC20 paymentToken,
        uint256[] calldata tokenIds,
        uint256[] calldata prices
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");

        uint256 length = tokenIds.length;
        for (uint256 i; i < length; i++) {
            IERC721(goldTnfts[uint256(goldIndex)]).safeTransferFrom(
                msg.sender,
                address(this),
                tokenIds[i]
            );
            IERC721(goldTnfts[uint256(goldIndex)]).approve(
                marketplace,
                tokenIds[i]
            );
            ITreasury(treasury).updateTrackerTnftExt(
                goldTnfts[uint256(goldIndex)],
                tokenIds[i],
                false
            );
            //update local tracking mechanism so that we can use it in RWACalculator
            tnftSalePlaced(
                ITangibleNFT(goldTnfts[uint256(goldIndex)]),
                tokenIds[i],
                true
            );
        }

        ITangibleMarketplace(marketplace).sellBatch(
            ITangibleNFT(goldTnfts[uint256(goldIndex)]),
            paymentToken,
            tokenIds,
            prices
        );
    }

    function modifyTnftSale(
        GOLD_WEIGHT goldIndex,
        uint256[] memory tokenIds,
        uint256[] memory prices
    ) external onlyRole(CONTROLLER_ROLE) {
        require(goldIndex < GOLD_WEIGHT.OUT, "no such gold");
        //put on sale
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        ITangibleMarketplace.Lot memory lot = ITangibleMarketplace(marketplace)
            .marketplace(goldTnfts[uint256(goldIndex)], tokenIds[0]);

        ITangibleMarketplace(marketplace).sellBatch(
            ITangibleNFT(goldTnfts[uint256(goldIndex)]),
            lot.paymentToken,
            tokenIds,
            prices
        );
    }

    struct HelperStruct {
        address gold;
        address treasury;
        bool found;
    }

    function sellFtnft(
        address ftnft,
        IERC20 paymentToken,
        uint256[] calldata shares,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        HelperStruct memory hs;
        hs.treasury = addressProvider.getAddress(TREASURY_ADDRESS);

        hs.gold = _fetchGoldAddressFromFraction(ftnft);
        hs.found;
        for (uint256 i; i < 4; i++) {
            if (goldTnfts[i] == hs.gold) {
                hs.found = true;
                break;
            }
        }

        require(hs.found, "fraction is not gold!");

        address[] memory contracts = new address[](2);
        bytes[] memory data = new bytes[](2);

        contracts[0] = ftnft;
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.approve.selector,
            abi.encode(address(this), tokenId)
        );
        data[1] = abi.encodePacked(
            GoldSellManager.sellFtnftCb.selector,
            abi.encode(
                ftnft,
                paymentToken,
                shares,
                tokenId,
                price,
                minPurchaseShare
            )
        );

        //update records
        ITreasury(hs.treasury).multicall(contracts, data);
    }

    function sellFtnftCb(
        address ftnft,
        IERC20 paymentToken,
        uint256[] calldata shares,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");
        //take it from treasury
        IERC721(ftnft).safeTransferFrom(treasury, address(this), tokenId);
        //approve
        IERC721(ftnft).approve(marketplace, tokenId);
        //update tracker correctly
        if (ITangibleFractionsNFT(ftnft).fractionShares(tokenId) == shares[0]) {
            ITreasury(treasury).updateTrackerFtnftExt(ftnft, tokenId, false);
            //update local tracking mechanism so that we can use it in RWACalculator
            ftnftSalePlaced(ITangibleFractionsNFT(ftnft), tokenId, true);
        } else {
            // we are not selling everything
            ITreasuryTracker(treasury).updateFractionData(
                address(ftnft),
                tokenId
            );
        }
        //put on sale
        ITangibleMarketplace(marketplace).sellFraction(
            ITangibleFractionsNFT(ftnft),
            paymentToken,
            tokenId,
            shares,
            price,
            minPurchaseShare
        );
    }

    function modifyFtnftSale(
        address ftnft,
        uint256 tokenId,
        uint256 price,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        HelperStruct memory hs;
        hs.gold = _fetchGoldAddressFromFraction(ftnft);
        hs.found;
        for (uint256 i; i < 4; i++) {
            if (goldTnfts[i] == hs.gold) {
                hs.found = true;
                break;
            }
        }

        require(hs.found, "fraction is not gold!");
        //put on sale
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        ITangibleMarketplace.LotFract memory lf = ITangibleMarketplace(
            marketplace
        ).marketplaceFract(ftnft, tokenId);
        uint256[] memory shares = new uint256[](2);

        ITangibleMarketplace(marketplace).sellFraction(
            ITangibleFractionsNFT(ftnft),
            lf.paymentToken,
            tokenId,
            shares,
            price,
            minPurchaseShare
        );
    }

    function sellFtnftInitial(
        GOLD_WEIGHT goldIndex,
        IERC20 paymentToken,
        uint256 keepShare,
        uint256 sellShare,
        uint256 tokenId,
        uint256 sellSharePrice,
        uint256 minPurchaseShare
    ) external onlyRole(CONTROLLER_ROLE) {
        require(goldIndex < GOLD_WEIGHT.OUT, "no such gold");
        address treasury = addressProvider.getAddress(TREASURY_ADDRESS);

        address[] memory contracts = new address[](2);
        bytes[] memory data = new bytes[](2);

        contracts[0] = goldTnfts[uint256(goldIndex)];
        contracts[1] = address(this);

        data[0] = abi.encodePacked(
            IERC721.approve.selector,
            abi.encode(address(this), tokenId)
        );
        data[1] = abi.encodePacked(
            GoldSellManager.sellFtnftInitialCb.selector,
            abi.encode(
                goldIndex,
                paymentToken,
                keepShare,
                sellShare,
                tokenId,
                sellSharePrice,
                minPurchaseShare
            )
        );

        ITreasury(treasury).multicall(contracts, data);
    }

    function sellFtnftInitialCb(
        GOLD_WEIGHT goldIndex,
        IERC20 paymentToken,
        uint256 keepShare,
        uint256 sellShare,
        uint256 tokenId,
        uint256 sellSharePrice,
        uint256 minPurchaseShare
    ) external {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        require(msg.sender == treasury, "not invoked by treasury");

        IERC721(goldTnfts[uint256(goldIndex)]).safeTransferFrom(
            treasury,
            address(this),
            tokenId
        );
        IERC721(goldTnfts[uint256(goldIndex)]).approve(marketplace, tokenId);
        ITangibleMarketplace(marketplace).sellFractionInitial(
            ITangibleNFT(goldTnfts[uint256(goldIndex)]),
            paymentToken,
            tokenId,
            keepShare,
            sellShare,
            sellSharePrice,
            minPurchaseShare
        );
        ITreasury(treasury).updateTrackerTnftExt(
            goldTnfts[uint256(goldIndex)],
            tokenId,
            false
        );
        if (keepShare != 0) {
            ITreasury(treasury).updateTrackerFtnftExt(
                latestReceivedNFT,
                latestReceivedToken,
                true
            );
        }
    }

    function _fetchGoldAddressFromFraction(address ftnft)
        internal
        view
        returns (address gold)
    {
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        IFactoryExt factory = ITangibleMarketplace(marketplace).factory();
        gold = address(
            factory.fractionToTnftAndId(ITangibleFractionsNFT(ftnft)).tnft
        );
    }

    function stopSellFtnft(address ftnft, uint256 tokenId)
        external
        onlyRole(CONTROLLER_ROLE)
    {
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        ITangibleMarketplace(marketplace).stopFractSale(
            ITangibleFractionsNFT(ftnft),
            tokenId
        );
        //update records
        IERC721(ftnft).safeTransferFrom(address(this), treasury, tokenId);
        ITreasury(treasury).updateTrackerFtnftExt(ftnft, tokenId, true);
        //update local tracking mechanism so that we can use it in RWACalculator
        ftnftSalePlaced(ITangibleFractionsNFT(ftnft), tokenId, false);
    }

    function stopSellTnft(GOLD_WEIGHT goldIndex, uint256[] calldata tokenIds)
        external
        onlyRole(CONTROLLER_ROLE)
    {
        require(goldIndex < GOLD_WEIGHT.OUT, "no such gold");
        (address marketplace, address treasury) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(TANGIBLE_MARKETPLACE_ADDRESS, TREASURY_ADDRESS)
            ),
            (address, address)
        );
        uint256 length = tokenIds.length;
        ITangibleMarketplace(marketplace).stopBatchSale(
            ITangibleNFT(goldTnfts[uint256(goldIndex)]),
            tokenIds
        );
        //update records
        for (uint256 i = 0; i < length; i++) {
            IERC721(goldTnfts[uint256(goldIndex)]).safeTransferFrom(
                address(this),
                treasury,
                tokenIds[i]
            );
            ITreasury(treasury).updateTrackerTnftExt(
                goldTnfts[uint256(goldIndex)],
                tokenIds[i],
                true
            );
            //update local tracking mechanism so that we can use it in RWACalculator
            tnftSalePlaced(
                ITangibleNFT(goldTnfts[uint256(goldIndex)]),
                tokenIds[i],
                false
            );
        }
    }

    function withdrawToken(IERC20 token) external {
        if (
            !hasRole(DEFAULT_ADMIN_ROLE, msg.sender) &&
            !hasRole(CONTROLLER_ROLE, msg.sender)
        ) {
            revert(
                string(
                    abi.encodePacked(
                        "AccessControl: account ",
                        Strings.toHexString(uint160(msg.sender), 20),
                        " is missing role ",
                        Strings.toHexString(uint256(DEFAULT_ADMIN_ROLE), 32),
                        " or ",
                        Strings.toHexString(uint256(CONTROLLER_ROLE), 32)
                    )
                )
            );
        }
        (address underlying, address tngbl) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(UNDERLYING_ADDRESS, TNGBL_ADDRESS)
            ),
            (address, address)
        );
        if ((address(token) == tngbl) || (address(token) == underlying)) {
            require(
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
                "tngbl and uderlying not alowed"
            );
        }
        token.safeTransfer(msg.sender, token.balanceOf(address(this)));
    }

    function onERC721Received(
        address operator,
        address seller,
        uint256 tokenId,
        bytes calldata data
    ) external override returns (bytes4) {
        return _onERC721Received(operator, seller, tokenId, data);
    }

    function _onERC721Received(
        address, /*operator*/
        address, /*seller*/
        uint256 tokenId, /*tokenId*/
        bytes calldata /*data*/
    ) private returns (bytes4) {
        latestReceivedNFT = msg.sender;
        latestReceivedToken = tokenId;
        return IERC721Receiver.onERC721Received.selector;
    }
}

contracts/managers/GoldPurchaseManager.s.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.9;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

import "../constants/addresses.sol";
import "../constants/roles.sol";
import "../interfaces/ITokenSwap.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IPriceOracle.sol";
import "../interfaces/ITreasuryTracker.sol";
import "../interfaces/IRWACalculator.sol";
import "../tangibleInterfaces/ITangibleMarketplace.sol";
import "../tangibleInterfaces/IInstantLiquidity.sol";
import "../tokens/interfaces/ITangibleERC20.sol";
import "../AddressAccessor.sol";
import "./PurchaseManager.sol";

contract GoldPurchaseManager is PurchaseManager, IERC721Receiver {
    using SafeERC20 for IERC20;

    enum GOLD_WEIGHT {
        XAU100,
        XAU250,
        XAU500,
        XAU1000,
        OUT
    }

    address private latestReceivedNFT;
    uint256 private latestReceivedToken;
    address[4] public goldTnfts;

    struct HelperStruct {
        address rwaCalculator;
        address treasury;
        IERC20 paymentToken;
        uint256 amount;
        uint256 amountOfPaymentToken;
        bool inRange;
    }

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function setGoldTnfts(address[4] memory _goldTnfts)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        goldTnfts = _goldTnfts;
    }

    function purchaseTnft(
        GOLD_WEIGHT goldIndex,
        uint256 fingerprint,
        uint256 tokenId,
        uint256 _years,
        bool onlyLock
    ) external onlyRole(CONTROLLER_ROLE) {
        require(goldIndex < GOLD_WEIGHT.OUT, "no such gold");
        //check payment token and swap if necessary
        HelperStruct memory hs;
        address[] memory contracts = new address[](3);
        contracts[2] = address(this);
        (hs.rwaCalculator, hs.treasury, contracts[0]) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(
                    RWA_CALCULATOR_ADDRESS,
                    TREASURY_ADDRESS,
                    UNDERLYING_ADDRESS
                )
            ),
            (address, address, address)
        );

        (hs.paymentToken, hs.amount, hs.inRange) = IRWACalculator(
            hs.rwaCalculator
        ).fetchPaymentTokenAndAmountTnft(
                goldTnfts[uint256(goldIndex)],
                fingerprint,
                tokenId,
                _years,
                tokenId == 0 ? true : false
            );
        contracts[1] = address(hs.paymentToken);
        require(hs.inRange, "price above range");
        // if treasury has paymentToken, use it
        if (hs.amount <= hs.paymentToken.balanceOf(hs.treasury)) {
            hs.amountOfPaymentToken = hs.amount;
            hs.amount = 0;
        } else {
            hs.amountOfPaymentToken = hs.paymentToken.balanceOf(hs.treasury);
            hs.amount -= hs.amountOfPaymentToken;
        }
        uint256 reserveAmount = _checkPaymentTokenAndAmountNeeded(
            hs.paymentToken,
            hs.amount
        );

        _validatePurchase(reserveAmount);

        bytes[] memory data = new bytes[](3);
        data[0] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), reserveAmount)
        );
        data[1] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), hs.amountOfPaymentToken)
        );
        data[2] = abi.encodePacked(
            GoldPurchaseManager.purchaseTnftCb.selector,
            abi.encode(
                goldIndex,
                hs.paymentToken,
                fingerprint,
                tokenId,
                _years,
                hs.amount,
                reserveAmount,
                hs.amountOfPaymentToken,
                onlyLock
            )
        );
        ITreasury(hs.treasury).multicall(contracts, data);
    }

    function purchaseTnftCb(
        GOLD_WEIGHT goldIndex,
        IERC20 paymentToken,
        uint256 fingerprint,
        uint256 tokenId,
        uint256 _years,
        uint256 amountToFillUp,
        uint256 reserveAmount,
        uint256 amountOfPaymentToken,
        bool onlyLock
    ) external {
        (address underlying, address marketplace, address treasury) = abi
            .decode(
                addressProvider.getAddresses(
                    abi.encode(
                        UNDERLYING_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        TREASURY_ADDRESS
                    )
                ),
                (address, address, address)
            );
        require(msg.sender == treasury, "not invoked by treasury");
        paymentToken.safeTransferFrom(
            treasury,
            address(this),
            amountOfPaymentToken
        );
        //take the underlying from treasury
        if (reserveAmount > 0) {
            IERC20(underlying).safeTransferFrom(
                treasury,
                address(this),
                reserveAmount
            );
            //convert to usdc
            _convertTreasuryTokenToPayment(
                paymentToken,
                reserveAmount,
                false,
                amountToFillUp + amountOfPaymentToken,
                amountToFillUp
            );
        } else {
            paymentToken.approve(marketplace, amountOfPaymentToken);
        }

        if (tokenId == 0) {
            ITangibleMarketplace(marketplace).buyUnminted(
                ITangibleNFT(goldTnfts[uint256(goldIndex)]),
                fingerprint,
                _years,
                onlyLock
            );
        } else {
            ITangibleMarketplace(marketplace).buy(
                ITangibleNFT(goldTnfts[uint256(goldIndex)]),
                tokenId,
                _years
            );
        }
        //send to treasury
        IERC721(goldTnfts[uint256(goldIndex)]).safeTransferFrom(
            address(this),
            treasury,
            latestReceivedToken
        );
        //send the remaining payment token
        if (paymentToken.balanceOf(address(this)) > 0) {
            paymentToken.safeTransfer(
                treasury,
                paymentToken.balanceOf(address(this))
            );
        }
        // update records
        ITreasury(treasury).updateTrackerTnftExt(
            goldTnfts[uint256(goldIndex)],
            latestReceivedToken,
            true
        );
    }

    function purchaseFtnft(
        address ftnft,
        uint256 fractTokenId,
        uint256 share
    ) external onlyRole(CONTROLLER_ROLE) {
        HelperStruct memory hs;
        address[] memory contracts = new address[](2);
        bytes[] memory data = new bytes[](2);
        contracts[1] = address(this);

        (hs.rwaCalculator, hs.treasury, contracts[0]) = abi.decode(
            addressProvider.getAddresses(
                abi.encode(
                    RWA_CALCULATOR_ADDRESS,
                    TREASURY_ADDRESS,
                    UNDERLYING_ADDRESS
                )
            ),
            (address, address, address)
        );
        (hs.paymentToken, hs.amount, hs.inRange) = IRWACalculator(
            hs.rwaCalculator
        ).fetchPaymentTokenAndAmountFtnft(ftnft, fractTokenId, share);
        require(hs.inRange, "price above range");
        // if treasury has paymentToken, use it
        if (hs.amount <= hs.paymentToken.balanceOf(hs.treasury)) {
            hs.amountOfPaymentToken = hs.amount;
            hs.amount = 0;
        } else {
            hs.amountOfPaymentToken = hs.paymentToken.balanceOf(hs.treasury);
            hs.amount -= hs.amountOfPaymentToken;
        }
        uint256 reserveAmount = _checkPaymentTokenAndAmountNeeded(
            hs.paymentToken,
            hs.amount
        );

        _validatePurchase(reserveAmount);

        address gold = _fetchGoldAddressFromFraction(ftnft);
        bool found;
        for (uint256 i; i < 4; i++) {
            if (goldTnfts[i] == gold) {
                found = true;
                break;
            }
        }

        require(found, "fraction is not gold!");

        data[0] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), reserveAmount)
        );
        data[1] = abi.encodePacked(
            IERC20.approve.selector,
            abi.encode(address(this), hs.amountOfPaymentToken)
        );
        data[2] = abi.encodePacked(
            GoldPurchaseManager.purchaseFtnftCb.selector,
            abi.encode(
                ftnft,
                hs.paymentToken,
                fractTokenId,
                share,
                reserveAmount,
                hs.amount,
                hs.amountOfPaymentToken
            )
        );

        ITreasury(hs.treasury).multicall(contracts, data);
    }

    function purchaseFtnftCb(
        address ftnft,
        IERC20 paymentToken,
        uint256 fractTokenId,
        uint256 share,
        uint256 reserveAmount,
        uint256 amountToFillUp,
        uint256 amountOfPaymentToken
    ) external {
        (address underlying, address marketplace, address treasury) = abi
            .decode(
                addressProvider.getAddresses(
                    abi.encode(
                        UNDERLYING_ADDRESS,
                        TANGIBLE_MARKETPLACE_ADDRESS,
                        TREASURY_ADDRESS
                    )
                ),
                (address, address, address)
            );
        require(msg.sender == treasury, "not invoked by treasury");
        // take payment token from treasury
        paymentToken.safeTransferFrom(
            treasury,
            address(this),
            amountOfPaymentToken
        );
        //take the underlying from treasury
        if (reserveAmount > 0) {
            IERC20(underlying).safeTransferFrom(
                treasury,
                address(this),
                reserveAmount
            );
            //convert to usdc
            _convertTreasuryTokenToPayment(
                paymentToken,
                reserveAmount,
                false,
                amountToFillUp + amountOfPaymentToken,
                amountToFillUp
            );
        } else {
            paymentToken.approve(marketplace, amountOfPaymentToken);
        }

        ITangibleMarketplace(marketplace).buyFraction(
            ITangibleFractionsNFT(ftnft),
            fractTokenId,
            share
        );
        //send to treasury
        IERC721(ftnft).safeTransferFrom(
            address(this),
            treasury,
            latestReceivedToken
        );
        //send the remaining payment token
        if (paymentToken.balanceOf(address(this)) > 0) {
            paymentToken.safeTransfer(
                treasury,
                paymentToken.balanceOf(address(this))
            );
        }
        //update records
        ITreasury(treasury).updateTrackerFtnftExt(
            ftnft,
            latestReceivedToken,
            true
        );
        //
    }

    function _fetchGoldAddressFromFraction(address ftnft)
        internal
        view
        returns (address gold)
    {
        address marketplace = addressProvider.getAddress(
            TANGIBLE_MARKETPLACE_ADDRESS
        );
        IFactoryExt factory = ITangibleMarketplace(marketplace).factory();
        gold = address(
            factory.fractionToTnftAndId(ITangibleFractionsNFT(ftnft)).tnft
        );
    }

    function onERC721Received(
        address operator,
        address seller,
        uint256 tokenId,
        bytes calldata data
    ) external override returns (bytes4) {
        return _onERC721Received(operator, seller, tokenId, data);
    }

    function _onERC721Received(
        address, /*operator*/
        address, /*seller*/
        uint256 tokenId, /*tokenId*/
        bytes calldata /*data*/
    ) private returns (bytes4) {
        latestReceivedNFT = msg.sender;
        latestReceivedToken = tokenId;
        return IERC721Receiver.onERC721Received.selector;
    }
}

